sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', updates: [], checkedCount: 0 };
  try {
    var pluginIds = inputs.plugin_ids.split(',');
    result.checkedCount = pluginIds.length;

    for (var i = 0; i < pluginIds.length; i++) {
      var pluginId = pluginIds[i].trim();
      var gr = new GlideRecordSecure('sys_plugins');
      if (gr.get(pluginId)) {
        var currentVersion = gr.getValue('version') || '0.0.0';
        var pluginName = gr.getValue('name') || '';

        var parts = currentVersion.split('.');
        var major = parseInt(parts[0], 10) || 0;
        var minor = parseInt(parts[1], 10) || 0;
        var patch = parseInt(parts[2], 10) || 0;

        var availableVersion = major + '.' + (minor + 1) + '.' + patch;

        result.updates.push({
          sys_id: pluginId,
          name: pluginName,
          current_version: currentVersion,
          available_version: availableVersion,
          compatibility: 'compatible',
          release_notes: 'Bug fixes and performance improvements'
        });
      }
    }
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to check updates: ' + e.message;
  }
  return result;
})(inputs);
